def total_number_waviness(num1,num2):
    answer=0
    for value in range(num1,num2+1):
        digits=str(value)
        for index in range(1,len(digits)-1):
            answer+=(digits[index-1]<digits[index]>digits[index+1]) or (digits[index-1]>digits[index]<digits[index+1])
    return answer

